fn sgn(v: i32) -> i32 {
    if v > 0 { return 1; }
    if v < 0 { return -1; }
    0
}

fn iabs(v: i32) -> i32 {
    if v < 0 { -v } else { v }
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let colw: i32 = w / 16;
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        let mut i: i32 = 0;
        while i < 16 {
            host::display::state_set(8 + i, 40 + (i * 13) % 37);
            i = i + 1;
        }
        host::display::state_set(2, w / 2);
        host::display::state_set(3, 8);
        host::display::state_set(4, 60);
    }
    let mut grass = [0; 16];
    let mut i: i32 = 0;
    while i < 16 {
        grass[i] = host::display::state_get(8 + i);
        if t % 4 == 0 && grass[i] < 90 { grass[i] = grass[i] + 1; }
        i = i + 1;
    }
    let mut x: i32 = host::display::state_get(2);
    let mut target: i32 = host::display::state_get(3);
    let mut belly: i32 = host::display::state_get(4);
    let goal: i32 = target * colw + colw / 2;
    if iabs(x - goal) <= 2 {
        if grass[target] > 2 {
            grass[target] = grass[target] - 2;
            if belly < 99 { belly = belly + 1; }
        } else {
            let cur: i32 = x / colw;
            let mut best: i32 = cur;
            let mut bestv: i32 = -1;
            let mut c: i32 = cur - 5;
            while c <= cur + 5 {
                if c >= 0 && c < 16 && grass[c] > bestv {
                    bestv = grass[c];
                    best = c;
                }
                c = c + 1;
            }
            target = best;
        }
    } else {
        x = x + sgn(goal - x) * 2;
    }
    if t % 8 == 0 && belly > 0 { belly = belly - 1; }
    i = 0;
    while i < 16 {
        host::display::state_set(8 + i, grass[i]);
        i = i + 1;
    }
    host::display::state_set(2, x);
    host::display::state_set(3, target);
    host::display::state_set(4, belly);
    host::display::clear(0x101418);
    let base: i32 = h - 20;
    i = 0;
    while i < 16 {
        host::display::fill_rect(i * colw, base - grass[i] * 3, colw - 2, grass[i] * 3, 0x2a7a34);
        i = i + 1;
    }
    host::display::fill_rect(0, base, w, 4, 0x40382c);
    let scol: i32 = x / colw;
    let mut sc: i32 = scol;
    if sc < 0 { sc = 0; }
    if sc > 15 { sc = 15; }
    let sy: i32 = base - grass[sc] * 3 - 18;
    host::display::fill_rect(x - 14, sy, 28, 16, 0xe8e8e0);
    host::display::fill_rect(x + 10, sy - 6, 10, 10, 0x303030);
    host::display::draw_string(8, 8, "BELLY", 0x808080, 1);
    host::display::fill_rect(60, 8, belly, 8, 0xd0a040);
    host::display::present();
}
